import{_ as s,I as t,o,c as d,b6 as a,j as l,J as r,w as c}from"./chunks/framework.BUXTSoD9.js";const k=JSON.parse('{"title":"Grocery E-Commerce Microservices System","description":"","frontmatter":{},"headers":[],"relativePath":"en/stage-2/assignments/simple-grocery-microservices/index.md","filePath":"en/stage-2/assignments/simple-grocery-microservices/index.md"}'),h={name:"en/stage-2/assignments/simple-grocery-microservices/index.md"},p={style:{margin:"32px 0"}};function m(u,e,g,b,y,v){const i=t("StepBar"),n=t("ClientOnly");return o(),d("div",null,[e[0]||(e[0]=a('<h1 id="grocery-e-commerce-microservices-system" tabindex="-1">Grocery E-Commerce Microservices System <a class="header-anchor" href="#grocery-e-commerce-microservices-system" aria-label="Permalink to “Grocery E-Commerce Microservices System”">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>This project requires you to build a grocery e-commerce microservices system from scratch, based on a real PRD. Unlike previous single-service projects, the backend here is split into multiple independent services by business domain, unified through an API gateway. You&#39;ll learn how to design service boundaries and handle cross-service data consistency.</p><p>This is the comprehensive practical section of Stage 2. Microservices architecture is very common in real-world applications. Once you understand service decomposition and gateway routing, you&#39;ll be able to handle more complex backend system designs.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to “Prerequisites”">​</a></h2><p>Before starting this project, you should already be familiar with:</p><ul><li>Frontend page design and component libraries (<a href="./../../frontend/ui-design/">UI Design</a>, <a href="./../../frontend/modern-component-library/">Modern Component Libraries</a>)</li><li>Backend API design and development (<a href="./../../backend/ai-interface-code/">API Code</a>)</li><li>Database fundamentals and Supabase (<a href="./../../backend/database-supabase/">Database to Supabase</a>)</li><li>Git workflow and deployment (<a href="./../../backend/git-workflow/">Git &amp; GitHub</a>, <a href="./../../backend/zeabur-deployment/">Web App Deployment</a>)</li></ul><h2 id="learning-objectives" tabindex="-1">Learning Objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to “Learning Objectives”">​</a></h2><p>After completing this project, you will be able to:</p><ol><li>Read a PRD and extract a development task list for a microservices system</li><li>Decompose service boundaries by business domain (auth, catalog, inventory, order)</li><li>Design and implement API gateway routing</li><li>Handle cross-service issues like inventory deduction and order consistency</li><li>Complete end-to-end integration and deliver a demo-ready microservices prototype</li></ol><h2 id="project-overview" tabindex="-1">Project Overview <a class="header-anchor" href="#project-overview" aria-label="Permalink to “Project Overview”">​</a></h2><p>You will build a grocery e-commerce microservices system:</p><table tabindex="0"><thead><tr><th>Subsystem</th><th>Responsibility</th></tr></thead><tbody><tr><td><strong>User Frontend</strong></td><td>Browse products, place orders, view order history</td></tr><tr><td><strong>Admin Portal</strong></td><td>Product management, inventory management, order management</td></tr></tbody></table><p>The backend is split into these services:</p><table tabindex="0"><thead><tr><th>Service</th><th>Responsibility</th></tr></thead><tbody><tr><td><strong>API Gateway</strong></td><td>Unified entry point, route forwarding, auth verification</td></tr><tr><td><strong>Auth Service</strong></td><td>User registration, login, JWT issuance</td></tr><tr><td><strong>Catalog Service</strong></td><td>Product information management</td></tr><tr><td><strong>Inventory Service</strong></td><td>Stock quantity management</td></tr><tr><td><strong>Order Service</strong></td><td>Order creation, status management</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">PRD</p><p>The requirements document for this project is on GitHub: <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/en/stage-2/assignments/simple-grocery-microservices/PRD.md" target="_blank" rel="noreferrer">View PRD</a></p></div>',16)),l("div",p,[r(n,null,{default:c(()=>[r(i,{active:0,items:[{title:"Requirements",description:"Read PRD, define service decomposition, pages, and transaction flow"},{title:"Scaffold",description:"Generate frontend, gateway, and service skeletons"},{title:"Iterate",description:"Add APIs module by module, fix inventory and order consistency"},{title:"Launch",description:"End-to-end testing, deploy, and prepare demo"}]})]),_:1})]),e[1]||(e[1]=a(`<h2 id="part-1-requirements-analysis" tabindex="-1">Part 1: Requirements Analysis <a class="header-anchor" href="#part-1-requirements-analysis" aria-label="Permalink to “Part 1: Requirements Analysis”">​</a></h2><h3 id="_1-1-read-the-prd" tabindex="-1">1.1 Read the PRD <a class="header-anchor" href="#_1-1-read-the-prd" aria-label="Permalink to “1.1 Read the PRD”">​</a></h3><p>Open the PRD document and answer these key questions:</p><ul><li>How should services be decomposed? What are the responsibility boundaries of each service?</li><li>What pages do the user frontend and admin portal each need?</li><li>What is the inventory deduction strategy after an order is placed? How to handle success / failure / timeout?</li><li>Which complex capabilities (distributed transactions, message queues) should be skipped in the first version?</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>If the above questions don&#39;t have clear answers, don&#39;t start coding. Unclear requirements are the most common cause of rework.</p></div><h3 id="_1-2-confirm-system-architecture" tabindex="-1">1.2 Confirm System Architecture <a class="header-anchor" href="#_1-2-confirm-system-architecture" aria-label="Permalink to “1.2 Confirm System Architecture”">​</a></h3><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; fe[&quot;Frontend Pages&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  fe --&gt; gw[&quot;API Gateway&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; auth[&quot;Auth Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; catalog[&quot;Catalog Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; inventory[&quot;Inventory Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; order[&quot;Order Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  order --&gt; inventory</span></span></code></pre></div><h2 id="part-2-project-scaffolding" tabindex="-1">Part 2: Project Scaffolding <a class="header-anchor" href="#part-2-project-scaffolding" aria-label="Permalink to “Part 2: Project Scaffolding”">​</a></h2><h3 id="_2-1-generate-project-structure" tabindex="-1">2.1 Generate Project Structure <a class="header-anchor" href="#_2-1-generate-project-structure" aria-label="Permalink to “2.1 Generate Project Structure”">​</a></h3><p>Prompt reference:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Based on the current PRD, help me generate a project scaffold for a grocery e-commerce microservices system.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Requirements:</span></span>
<span class="line"><span>1. Generate user frontend and admin portal skeletons</span></span>
<span class="line"><span>2. Generate five directories: api-gateway, auth-service, catalog-service, inventory-service, order-service</span></span>
<span class="line"><span>3. Each service should only have a minimal runnable entry point</span></span>
<span class="line"><span>4. Don&#39;t connect to a real database or payment system yet</span></span></code></pre></div><h3 id="_2-2-verify-project-structure" tabindex="-1">2.2 Verify Project Structure <a class="header-anchor" href="#_2-2-verify-project-structure" aria-label="Permalink to “2.2 Verify Project Structure”">​</a></h3><p>Check each item:</p><ul><li>[ ] Five service directories have clear structure</li><li>[ ] API Gateway starts and forwards requests</li><li>[ ] Each service&#39;s health check endpoint works</li><li>[ ] User frontend and admin portal pages are accessible</li></ul><h2 id="part-3-iterative-development" tabindex="-1">Part 3: Iterative Development <a class="header-anchor" href="#part-3-iterative-development" aria-label="Permalink to “Part 3: Iterative Development”">​</a></h2><h3 id="_3-1-module-by-module-progress" tabindex="-1">3.1 Module-by-Module Progress <a class="header-anchor" href="#_3-1-module-by-module-progress" aria-label="Permalink to “3.1 Module-by-Module Progress”">​</a></h3><ol><li><strong>API Gateway</strong>: Route configuration, JWT verification middleware</li><li><strong>Auth Service</strong>: Registration, login, JWT issuance</li><li><strong>Catalog Service</strong>: Product CRUD, list queries</li><li><strong>Inventory Service</strong>: Stock queries, stock deduction</li><li><strong>Order Service</strong>: Order creation, status transitions, inventory integration</li><li><strong>Admin Portal</strong>: Product management, inventory management, order management</li></ol><h3 id="_3-2-module-self-check" tabindex="-1">3.2 Module Self-Check <a class="header-anchor" href="#_3-2-module-self-check" aria-label="Permalink to “3.2 Module Self-Check”">​</a></h3><table tabindex="0"><thead><tr><th>Check Item</th><th>Verification Method</th></tr></thead><tbody><tr><td>Gateway routing</td><td>Are service APIs correctly forwarded through the gateway?</td></tr><tr><td>Auth isolation</td><td>Are user and admin APIs properly separated?</td></tr><tr><td>Data consistency</td><td>Are product and inventory data in sync?</td></tr><tr><td>Transaction loop</td><td>After ordering, are inventory deduction and order status consistent?</td></tr><tr><td>Failure handling</td><td>Is there a compensation mechanism for insufficient stock or timeout?</td></tr></tbody></table><h2 id="part-4-integration-launch" tabindex="-1">Part 4: Integration &amp; Launch <a class="header-anchor" href="#part-4-integration-launch" aria-label="Permalink to “Part 4: Integration &amp; Launch”">​</a></h2><h3 id="_4-1-end-to-end-testing" tabindex="-1">4.1 End-to-End Testing <a class="header-anchor" href="#_4-1-end-to-end-testing" aria-label="Permalink to “4.1 End-to-End Testing”">​</a></h3><p>At minimum, verify these scenarios:</p><ul><li>Browse products → Add to cart → Place order → View order</li><li>Admin → Add product → Update inventory → View orders</li></ul><h2 id="deliverables" tabindex="-1">Deliverables <a class="header-anchor" href="#deliverables" aria-label="Permalink to “Deliverables”">​</a></h2><p>After completing this project, submit the following:</p><ul><li>[ ] Accessible live demo link</li><li>[ ] Source code repository link (with README)</li><li>[ ] PRD document</li><li>[ ] Core page screenshots (product list, order page, order history, admin dashboard)</li><li>[ ] 60-second demo video</li></ul><h2 id="grading-criteria" tabindex="-1">Grading Criteria <a class="header-anchor" href="#grading-criteria" aria-label="Permalink to “Grading Criteria”">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>Basic Requirements</th><th>Advanced Requirements</th></tr></thead><tbody><tr><td>PRD Alignment</td><td>Pages, features, and service decomposition basically match PRD</td><td>Can clearly explain service decomposition rationale</td></tr><tr><td>Product Loop</td><td>Browse → Order → Inventory deduction → View order works end-to-end</td><td>Order timeout or insufficient stock has compensation mechanism</td></tr><tr><td>Service Architecture</td><td>Each service starts independently, accessible through gateway</td><td>Inter-service communication has error handling and retry</td></tr><tr><td>Admin Capability</td><td>Product, inventory, and order management are functional</td><td>Admin portal has data statistics</td></tr><tr><td>Engineering Completeness</td><td>Frontend, gateway, services, database pipeline connected</td><td>Has Docker Compose or similar orchestration</td></tr></tbody></table><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to “References”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">UI Design</a></li><li><a href="./../../frontend/modern-component-library/">Modern Component Libraries</a></li><li><a href="./../../backend/database-supabase/">Database to Supabase</a></li><li><a href="./../../backend/ai-interface-code/">API Code with LLM Assistance</a></li><li><a href="./../../backend/git-workflow/">Git &amp; GitHub Workflow</a></li><li><a href="./../../backend/zeabur-deployment/">Web App Deployment</a></li></ul>`,30))])}const P=s(h,[["render",m]]);export{k as __pageData,P as default};
